-- Close untouched warning cases generated by an already completed violation correction.
WITH correction_warnings AS (
    SELECT DISTINCT ON (warning.exception_case_id)
           warning.exception_case_id, violation.exception_case_id AS violation_id, correction.user_id
    FROM fgc.audit_log correction
    JOIN fgc.exception_case violation ON violation.exception_case_id::text = correction.entity_id
    JOIN fgc.cap_check original ON original.cap_check_id = violation.cap_check_id
        OR (violation.cap_check_id IS NULL AND violation.source_entity_type = 'CAP_CHECK'
            AND original.cap_check_id::text = violation.source_entity_id)
    JOIN fgc.commission_transaction payment
        ON payment.commission_transaction_id::text = correction.after_value->>'paymentId'
    JOIN fgc.cap_check recheck ON recheck.candidate_transaction_id = payment.commission_transaction_id
        AND recheck.contract_id = original.contract_id
        AND recheck.payment_stage = original.payment_stage
        AND recheck.cap_rule_set_id = original.cap_rule_set_id
    JOIN fgc.exception_case warning ON warning.cap_check_id = recheck.cap_check_id
        AND warning.source_entity_type = 'COMMISSION_TRANSACTION'
        AND warning.source_entity_id = payment.commission_transaction_id::text
    WHERE correction.entity_type = 'EXCEPTION_CASE' AND correction.action_code = 'EXCEPTION_PAYMENT_CORRECTION'
      AND correction.user_id IS NOT NULL
      AND violation.exception_type = 'CAP_VIOLATION' AND violation.status = 'RESOLVED'
      AND original.result_status = 'VIOLATION' AND recheck.result_status = 'WARNING'
      AND warning.exception_type = 'CAP_WARNING' AND warning.status = 'NEW'
      AND recheck.checked_at BETWEEN violation.created_at AND correction.occurred_at
      AND warning.created_at <= correction.occurred_at
      AND payment.status = 'CONFIRMED'
      AND (payment.confirm_idempotency_key = CONCAT('EXCP-', violation.exception_case_id, '-', payment.commission_transaction_id)
           OR EXISTS (SELECT 1 FROM fgc.payment_journal_correction journal
                      WHERE journal.replacement_payment_id = payment.commission_transaction_id
                        AND payment.confirm_idempotency_key = CONCAT('EXCP-JC-', journal.correction_group_key)))
      AND NOT EXISTS (SELECT 1 FROM fgc.exception_action action WHERE action.exception_case_id = warning.exception_case_id)
    ORDER BY warning.exception_case_id, correction.audit_log_id DESC
), resolved_warnings AS (
    UPDATE fgc.exception_case warning
    SET status = 'RESOLVED', resolved_at = clock_timestamp()
    FROM correction_warnings matched
    WHERE warning.exception_case_id = matched.exception_case_id AND warning.status = 'NEW'
    RETURNING warning.exception_case_id, matched.violation_id, matched.user_id, warning.resolved_at
)
INSERT INTO fgc.exception_action
    (exception_case_id, action_seq, from_status, to_status, action_type, reason, evidence_ref, action_by, action_at)
SELECT exception_case_id, 1, 'NEW', 'RESOLVED', 'CORRECT',
       CONCAT('위반 예외 ', violation_id, '번 정정 후 한도 주의 판정 확인'),
       CONCAT('EXCP-', violation_id), user_id, resolved_at
FROM resolved_warnings;
